-- Carte d'A Piaghja : produits éditables depuis le back-office
CREATE TABLE IF NOT EXISTS carte (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  panel INTEGER NOT NULL,
  categorie TEXT NOT NULL,
  nom TEXT NOT NULL,
  descr TEXT,
  prix TEXT NOT NULL,
  ordre INTEGER NOT NULL,
  visible INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX IF NOT EXISTS idx_carte_panel ON carte (panel, ordre);
DELETE FROM carte;
